static void inject(Object target, Object dependency) throws Exception {
    for (Field f : target.getClass().getDeclaredFields()) {
        if (f.isAnnotationPresent(MyInject.class) && f.getType().isInstance(dependency)) {
            f.setAccessible(true);
            f.set(target, dependency);
        }
    }
}

