static <T> T map(Object source, Class<T> targetType) throws Exception {
    T target = targetType.getDeclaredConstructor().newInstance();
    for (Field srcField : source.getClass().getDeclaredFields()) {
        Field dstField = targetType.getDeclaredField(srcField.getName());
        srcField.setAccessible(true);
        dstField.setAccessible(true);
        dstField.set(target, srcField.get(source));
    }
    return target;
}

