static String toSimpleJsonIgnoring(Object obj) throws Exception {
    StringBuilder sb = new StringBuilder("{");
    List<Field> visible = new ArrayList<>();
    for (Field f : obj.getClass().getDeclaredFields()) {
        if (!f.isAnnotationPresent(JsonIgnore.class)) visible.add(f);
    }
    for (int i = 0; i < visible.size(); i++) {
        Field f = visible.get(i);
        f.setAccessible(true);
        Object v = f.get(obj);
        sb.append("\"").append(f.getName()).append("\":")
          .append(v instanceof String ? "\"" + v + "\"" : v);
        if (i < visible.size() - 1) sb.append(",");
    }
    return sb.append("}").toString();
}

