@SuppressWarnings("unchecked")
static <T> T create(Class<T> type, Map<Class<?>, Object> registry) throws Exception {
    if (registry.containsKey(type)) return (T) registry.get(type);
    Constructor<?> ctor = type.getConstructors()[0];
    Class<?>[] paramTypes = ctor.getParameterTypes();
    Object[] args = new Object[paramTypes.length];
    for (int i = 0; i < paramTypes.length; i++) {
        args[i] = registry.containsKey(paramTypes[i])
            ? registry.get(paramTypes[i])
            : create(paramTypes[i], registry); // rekurencja
    }
    return (T) ctor.newInstance(args);
}

