@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
@interface NotBlank {}
@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
@interface Positive {}

class RegistrationForm {
    @NotBlank
    String name;
    @Positive
    int age;
}

static List<String> validate(Object obj) throws Exception {
    List<String> errors = new ArrayList<>();
    for (Field f : obj.getClass().getDeclaredFields()) {
        f.setAccessible(true);
        if (f.isAnnotationPresent(NotBlank.class)) {
            String v = (String) f.get(obj);
            if (v == null || v.isBlank()) errors.add(f.getName() + " puste");
        }
        if (f.isAnnotationPresent(Positive.class)) {
            int v = f.getInt(obj);
            if (v <= 0) errors.add(f.getName() + " musi byc dodatnie");
        }
    }
    return errors;
}

