@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
@interface OnEvent {
    String value();
}

class EventHandlers {
    @OnEvent("ORDER_CREATED")
    void onCreated() { System.out.println("Zamowienie utworzone"); }
    @OnEvent("ORDER_CANCELLED")
    void onCancelled() { System.out.println("Zamowienie anulowane"); }
}

static void dispatch(Object handlersObj, String eventName) throws Exception {
    for (Method m : handlersObj.getClass().getDeclaredMethods()) {
        OnEvent oe = m.getAnnotation(OnEvent.class);
        if (oe != null && oe.value().equals(eventName)) {
            m.invoke(handlersObj);
        }
    }
}

dispatch(new EventHandlers(), "ORDER_CREATED");

static void copyFieldsRespectingIgnore(Object source, Object target) throws Exception {
    for (Field f : source.getClass().getDeclaredFields()) {
        if (f.isAnnotationPresent(JsonIgnore.class)) continue;
        f.setAccessible(true);
        f.set(target, f.get(source));
    }
}

