@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
@interface MySetup {}

static void runTestsWithSetup(Class<?> testClass) throws Exception {
    Object instance = testClass.getDeclaredConstructor().newInstance();
    Method setupMethod = null;
    for (Method m : testClass.getDeclaredMethods()) {
        if (m.isAnnotationPresent(MySetup.class)) setupMethod = m;
    }
    for (Method m : testClass.getDeclaredMethods()) {
        if (m.isAnnotationPresent(MyTest.class)) {
            if (setupMethod != null) setupMethod.invoke(instance);
            m.invoke(instance);
        }
    }
}

class ReflectionCache {
    static final Map<Class<?>, Method[]> cache = new HashMap<>();
    static Method[] methodsOf(Class<?> type) {
        return cache.computeIfAbsent(type, Class::getDeclaredMethods);
    }
}

long t1 = System.nanoTime();
for (int i = 0; i < 100_000; i++) ReflectionCache.methodsOf(String.class);
long withCache = System.nanoTime() - t1;

long t2 = System.nanoTime();
for (int i = 0; i < 100_000; i++) String.class.getDeclaredMethods();
long withoutCache = System.nanoTime() - t2;

System.out.println("Z cache: " + withCache + "ns, bez cache: " + withoutCache + "ns");

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
@interface Column {
    String value();
}

class ProductEntity {
    @Column("product_id")
    private Long id;
    @Column("product_name")
    private String name;
    @Column("product_price")
    private Double price;
    private ProductEntity() {}
    @Override
    public String toString() { return id + " " + name + " " + price; }
}

static <T> List<T> mapRows(Class<T> entityType, List<Map<String, Object>> rawRows) throws Exception {
    List<T> result = new ArrayList<>();
    for (Map<String, Object> row : rawRows) {
        T entity = entityType.getDeclaredConstructor().newInstance();
        for (Field f : entityType.getDeclaredFields()) {
            Column col = f.getAnnotation(Column.class);
            if (col != null) {
                f.setAccessible(true);
                f.set(entity, row.get(col.value()));
            }
        }
        result.add(entity);
    }
    return result;
}

List<ProductEntity> products = mapRows(ProductEntity.class, List.of(
    Map.of("product_id", 1L, "product_name", "Laptop", "product_price", 3000.0)));
